function shuffle(r) {
    var t = r.slice();
    for (let r = t.length - 1; 0 < r; r--) {
        var a = Math.floor(Math.random() * (r + 1));
        [t[r], t[a]] = [t[a], t[r]];
    }
    return t;
}

function next() {
    let idx = source.getVariable();
    idx = parseInt(idx);
    if (isNaN(idx) || idx < 0 || idx >= apis.length) {
        idx = Math.floor(Math.random() * apis.length);
    } else {
        idx = (idx + 1) % apis.length;
    }

    source.setVariable(idx);
    let apii = apis[idx];

    java.toast("接口检测中...");

    java.toast(`✅切换成功\n当前接口：${apii[0]}\n是否支持FHD发言人：${apii[1] ? "支持" : "不支持"}\n${check(apii)}`);
}

function status() {
    let idx = source.getVariable();
    idx = parseInt(idx);
    if (isNaN(idx) || idx < 0 || idx >= apis.length) {
        java.toast(`\n❌尚未初始化`);
    } else {
        let apii = apis[idx];
        java.toast(`当前接口：${apii[0]}\n是否支持FHD发言人：${apii[1] ? "支持" : "不支持"}\n${check(apii)}`);
    }
}

function check(api) {
    let isPost = !!api[3];
    let testu = isPost
        ? api[0]
        : `${api[0]}?t=这是一段测试文本&v=zh-CN-XiaoxiaoNeural&r=-10&p=0&s=${source.getVariable()}&api_key=${api[2] ?? ""}`;
    let json = `{
    "input":"这是一段测试文本",
    "voice":"zh-CN-XiaozhenNeural",
    "speed":1,
    "pitch":"0",
    "style":"general"
  }`;
    java.log(testu);

    try {
        let conn = org.jsoup.Jsoup.connect(testu)
            .method(isPost ? org.jsoup.Connection.Method.POST : org.jsoup.Connection.Method.GET)
            .timeout(5000)
            .ignoreContentType(true);

        if (isPost) {
            conn.header("Content-Type", "application/json").requestBody(json);
        }
        conn.execute();
        return "✅接口正常";
    } catch (e) {
        java.log(e);
        return "❌接口异常";
    }
}

